    expect(cola.cancelar("a")).toBe(true);
    expect(senal?.aborted).toBe(true);
    expect(cola.estado("a").estado).toBe(ESTADOS.CANCELADO);
    expect(cola.cancelar("a")).toBe(false);
    d.resolver({ codigo: 0 });
    await espera();
    expect(cola.estado("a").estado).toBe(ESTADOS.CANCELADO);
